(function(root){
  const MAX_FILE_BYTES=20*1024*1024,MAX_TEXT_LENGTH=1000000;
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function normalize(text){return String(text).replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').replace(/\0/g,'').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim()}
  function format(filename,mime=''){const extension=String(filename).toLowerCase().split('.').pop();if(['txt','md','markdown','html','htm','pdf','docx'].includes(extension))return {markdown:'md',htm:'html'}[extension]||extension;if(mime==='text/plain')return 'txt';if(mime==='text/markdown')return 'md';if(mime==='text/html')return 'html';if(mime==='application/pdf')return 'pdf';return null}
  function validateFile(file){if(!file.size)throw Error('empty');if(file.size>MAX_FILE_BYTES)throw Error('large');const kind=format(file.name,file.type);if(!kind)throw Error('unsupported');return kind}
  function makeDocument({title,text,source='',format:kind='txt',blob=null,id,date=Date.now()}){text=normalize(text);if(!text&&!blob)throw Error('empty');if(text.length>MAX_TEXT_LENGTH)throw Error('long');return {id:id||globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),title:normalize(title||'').slice(0,160)||text.split('\n')[0]?.replace(/^#+\s*/,'').slice(0,80)||'Untitled',text,source,format:kind,blob,date,progress:0}}
  function wordCount(text){const cjk=(text.match(/[\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af]/g)||[]).length;const words=text.replace(/[\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af]/g,' ').match(/[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu)||[];return cjk+words.length}
  function progress(scrollTop,height,viewport){const max=height-viewport;return max<=1?1:Math.min(1,Math.max(0,scrollTop/max))}
  function renderText(text,markdown=false){const lines=normalize(text).split('\n');let result=[],paragraph=[],code=[],inCode=false;const flush=()=>{if(paragraph.length){result.push('<p>'+paragraph.map(escape).join('<br>')+'</p>');paragraph=[]}};for(const line of lines){if(markdown&&/^\s*```/.test(line)){flush();if(inCode){result.push('<pre><code>'+escape(code.join('\n'))+'</code></pre>');code=[]}inCode=!inCode;continue}if(inCode){code.push(line);continue}const heading=markdown&&line.match(/^(#{1,3})\s+(.+)$/);if(heading){flush();const level=heading[1].length+1;result.push(`<h${level}>${escape(heading[2])}</h${level}>`)}else if(!line.trim())flush();else paragraph.push(line)}flush();if(code.length)result.push('<pre><code>'+escape(code.join('\n'))+'</code></pre>');return result.join('')}
  function decode(buffer){const bytes=new Uint8Array(buffer);if(bytes[0]===255&&bytes[1]===254)return new TextDecoder('utf-16le').decode(bytes);if(bytes[0]===254&&bytes[1]===255)return new TextDecoder('utf-16be').decode(bytes);try{return new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch{return new TextDecoder('gb18030').decode(bytes)}}
  const api={MAX_FILE_BYTES,MAX_TEXT_LENGTH,normalize,format,validateFile,makeDocument,wordCount,progress,renderText,decode};root.ReadingCore=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
